"""Mechanical static declarations from the frozen, source-checked T field map."""
import json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
inv=json.loads((ROOT/'rust/verification/pulsar_lifecycle/freeze/field-and-operation-map.json').read_text())
types={'longdouble':'Float','double':'f64','float':'f32','int':'i32','unsigned':'u32','uint64_t':'u64','char':'u8','param_label':'i32','constraint_label':'i32','enum constraint':'Constraint','enum series_type':'SeriesType','paramDerivFunc':'Option<Callback<ParamDerivFunc>>','constraintDerivFunc':'Option<Callback<ConstraintDerivFunc>>','paramUpdateFunc':'Option<Callback<ParamUpdateFunc>>'}
names={'pulsar':'SourcePulsar','storePrecision':'StorePrecision','FitInfo':'FitInfo','FitOutput':'FitOutput','observation':'SourceObservation'}
constants={m[1]:int(m[2]) for s in inv['constants'] if (m:=re.match(r'#define\s+(\w+)\s+(\d+)\s*$',s.strip()))}
used={v for k in names for f in inv['types'][k] for e in f['extents'] for v in re.findall(r'\b[A-Z][\w]+\b',e)}
lines=['//! Static source counterparts generated by generate_storage.py; no native ABI layout.','//! Scalars and bytes are unwritten until a source or explicit caller write.','#![allow(non_snake_case, non_camel_case_types)]','use rug::Float;','use crate::tempo2::{ParameterStore, SourceObservation, MAX_PARAMS};','use crate::pulsar_lifecycle::{ObservationView, MatrixOwner, PayloadView};','']
for n in sorted(used-{'MAX_PARAMS'}):lines.append(f'pub const {n}: usize = {constants[n]};')
for orig,rust in [('constraint','Constraint'),('series_type','SeriesType')]:
 enum=next(e for e in inv['enums'] if e.startswith('enum '+orig+' '));variants=[v.strip() for v in enum.split('{')[1].split('}')[0].split(',') if v.strip()]
 lines+=['#[repr(i32)]','#[derive(Clone, Copy, Debug, PartialEq, Eq)]',f'pub enum {rust} {{']+[f'    {v} = {i},' for i,v in enumerate(variants)]+['}']
lines+=['/// Logical callback identity is retained independently of its function address.', '#[derive(Clone, Copy, Debug)]','pub struct Callback<F> { pub identity: u64, pub callable: F }', 'pub type ParamDerivFunc = fn(&mut crate::pulsar_lifecycle::PulsarContext, i32, f64, i32, i32, i32) -> f64;', 'pub type ConstraintDerivFunc = fn(&mut crate::pulsar_lifecycle::PulsarContext, i32, i32, i32, i32, i32, Option<&[Option<u8>]>) -> f64;', 'pub type ParamUpdateFunc = fn(&mut crate::pulsar_lifecycle::PulsarContext, i32, i32, i32, f64, f64);']
for kind in ['storePrecision','FitOutput','FitInfo','pulsar']:
 fields=inv['types'][kind];defs=[];defaults=[]
 for f in fields:
  n=f['name'];t=f['type'];ext=f['extents']
  if t=='parameter': rt='ParameterStore';init='ParameterStore::unwritten()';ext=[]
  elif f['pointers']:
   base='MatrixOwner' if t=='double' else 'ObservationView' if t=='observation' else 'PayloadView'
   rt=f'Option<Option<{base}>>';init='None'
  elif t in names:rt=names[t];init=f'{rt}::default()'
  else:rt=f'Option<{types[t]}>';init='None'
  for d in reversed(ext[1:]):rt=f'[{rt}; {d}]';init=f'std::array::from_fn(|_| {init})'
  if ext:
   rt=f'Box<[{rt}; {ext[0]}]>'
   init=f'(0..{ext[0]}).map(|_| {init}).collect::<Vec<_>>().into_boxed_slice().try_into().ok().unwrap()'
  defs.append(f'    pub {n}: {rt},');defaults.append(f'            {n}: {init},')
 lines+=['#[derive(Clone, Debug)]',f'pub struct {names[kind]} {{',*defs,'}',f'impl Default for {names[kind]} {{','    fn default() -> Self {','        Self {',*defaults,'        }','    }','}']
(ROOT/'rust/src/pulsar.rs').write_text('\n'.join(lines)+'\n')
